// Acceptance test for docs/cycle_frame_spec.md. Do not edit this file when implementing the spec.
// Part 1 recomputes the spec's figures from raw data with its own code. Part 2 holds the site's
// engine to those figures and starts to apply once docs/js/cycle-engine.js exists.
import fs from 'fs'; import vm from 'vm'; import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const START = '2012-06-01', ASOF = '2026-11-13';
const D = JSON.parse(fs.readFileSync('docs/data/dashboard_data.json', 'utf8')).etfs;
const bars = t => D[t].history.filter(b => b && b.close != null && b.date <= ASOF);
const ctx = { console, Math, Date, JSON, Map, Set, Float64Array, Array, Object, Number, isFinite, parseFloat, parseInt, Infinity };
vm.createContext(ctx);
vm.runInContext(fs.readFileSync('docs/js/config.js', 'utf8') + '\n;globalThis.__C = CONFIG;', ctx);
vm.runInContext(fs.readFileSync('docs/js/volume-studies.js', 'utf8') + '\n;globalThis.__V = VolumeStudies;', ctx);
const VS = ctx.__V;
let failed = 0;
const check = (name, ok, detail) => { if (!ok) failed++; console.log((ok ? 'ok   ' : 'FAIL ') + name + (detail ? '  ' + detail : '')); };
const median = a => { const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

// ── Reference scorer ────────────────────────────────────────────────────────────────────────
function pivots(p, pct = 30) {
    const thr = pct / 100, out = []; let dir = null, k = 0;
    for (let i = 1; i < p.length; i++) {
        const ch = (p[i] - p[k]) / p[k];
        if (dir === null) { if (ch >= thr) { out.push({ i: k, type: 'T' }); dir = 'up'; k = i; } else if (ch <= -thr) { out.push({ i: k, type: 'P' }); dir = 'dn'; k = i; } }
        else if (dir === 'up') { if (p[i] >= p[k]) k = i; else if ((p[k] - p[i]) / p[k] >= thr) { out.push({ i: k, type: 'P' }); dir = 'dn'; k = i; } }
        else { if (p[i] <= p[k]) k = i; else if ((p[i] - p[k]) / p[k] >= thr) { out.push({ i: k, type: 'T' }); dir = 'up'; k = i; } }
    }
    return out;
}
function episodes(mask, gap = 10, skip = 60) { const out = []; let last = -1e9; for (let i = skip; i < mask.length; i++) if (mask[i]) { if (i - last > gap) out.push(i); last = i; } return out; }
function entry(c, piv, t) {
    const pk = piv.find(x => x.type === 'P' && x.i > t); if (!pk) return null;
    let lo = Infinity; for (let j = t; j <= pk.i; j++) lo = Math.min(lo, c[j]);
    const nearLow = piv.some(x => x.type === 'T' && Math.abs(x.i - t) <= 10 && c[t] <= c[x.i] * 1.15);
    let worked = false;
    for (let j = t + 1; j < Math.min(c.length, t + 250); j++) { const r = c[j] / c[t] - 1; if (r >= 0.30) { worked = true; break; } if (r <= -0.20) break; }
    return { run: c[pk.i] / c[t] - 1, heat: lo / c[t] - 1, nearLow, worked };
}
function record(c, mask) {
    const piv = pivots(c), rows = episodes(mask).map(t => entry(c, piv, t)).filter(Boolean);
    const all = []; for (let i = 60; i < c.length; i++) { const e = entry(c, piv, i); if (e) all.push(e); }
    const pct = (a, f) => a.length ? a.filter(f).length / a.length * 100 : null;
    return { n: rows.length, worked: rows.filter(r => r.worked).length, workedPct: pct(rows, r => r.worked), nearLowPct: pct(rows, r => r.nearLow),
        run: rows.length ? median(rows.map(r => r.run)) * 100 : null, heat: rows.length ? median(rows.map(r => r.heat)) * 100 : null,
        any: { workedPct: pct(all, r => r.worked), nearLowPct: pct(all, r => r.nearLow) } };
}
// Features are computed on the full history; scoring uses sessions from START.
function rvol(b) { const dv = b.map(x => x.close * (x.volume || 0)), out = new Array(b.length).fill(NaN); for (let i = 63; i < b.length; i++) { const m = median(dv.slice(i - 63, i)); if (m > 0) out[i] = dv[i] / m; } return out; }
function sideVol(us, ca) {
    const ru = rvol(us), rc = rvol(ca), byDate = new Map(ca.map((b, i) => [b.date, rc[i]])), out = new Array(us.length).fill(NaN); let carry = NaN, age = 99;
    for (let i = 0; i < us.length; i++) {
        let v = byDate.get(us[i].date); if (v != null && !isNaN(v)) { carry = v; age = 0; } else if (++age <= 2) v = carry; else v = NaN;
        const xs = [ru[i], v].filter(x => x != null && !isNaN(x)); out[i] = xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : NaN;
    }
    return out;
}
function maskA(kold, hnd) {
    const sv = sideVol(kold, hnd), m = new Array(kold.length).fill(false);
    for (let i = 10; i < kold.length; i++) { let k = 0; for (let j = i - 4; j <= i; j++) if (sv[j] >= 1.5) k++; m[i] = k >= 3 && kold[i].close <= kold[i - 10].close; }
    return m;
}
function maskK(kold, boil) {
    const imp = VS.computeInvariantPVTEngine(kold, 'KOLD', boil).impulse, n = kold.length, ip = new Array(n), z = new Array(n).fill(NaN), byDate = new Map(); let acc = 0;
    for (let i = 0; i < n; i++) { acc += imp[i] || 0; ip[i] = acc; }
    for (let i = 62; i < n; i++) { const w = ip.slice(i - 62, i + 1), mu = w.reduce((a, b) => a + b, 0) / 63, sd = Math.sqrt(w.reduce((a, b) => a + (b - mu) ** 2, 0) / 62); if (sd > 0) z[i] = (ip[i] - mu) / sd; }
    for (let i = 71; i < n; i++) { let mx = -Infinity, okAll = true; for (let j = i - 9; j <= i; j++) { if (isNaN(z[j])) okAll = false; else mx = Math.max(mx, z[j]); } byDate.set(kold[i].date, okAll && mx >= 1.5 && imp[i] < -0.5); }
    return boil.map(b => !!byDate.get(b.date));
}
const windowOf = (b, m) => { const s = b.findIndex(x => x.date >= START); return { c: b.slice(s).map(x => x.close), m: m.slice(s), dates: b.slice(s).map(x => x.date) }; };

const B = { BOIL: bars('BOIL'), KOLD: bars('KOLD'), HNU: bars('HNU.TO'), HND: bars('HND.TO') };
const mA = maskA(B.KOLD, B.HND), mK = maskK(B.KOLD, B.BOIL);
const wA = windowOf(B.KOLD, mA), wK = windowOf(B.BOIL, mK);
const refA = record(wA.c, wA.m), refK = record(wK.c, wK.m);
const fmt = r => `${r.worked}/${r.n} worked (${r.workedPct.toFixed(0)}% vs any day ${r.any.workedPct.toFixed(0)}%), near low ${r.nearLowPct.toFixed(0)}%, run ${r.run.toFixed(0)}%, heat ${r.heat.toFixed(0)}%`;
console.log('reference A on KOLD: ' + fmt(refA)); console.log('reference K on BOIL: ' + fmt(refK));

// ── Part 1: the reference must still produce the spec's figures ─────────────────────────────
const FROZEN = JSON.parse(fs.readFileSync(new URL('./cycle_acceptance_frozen.json', import.meta.url), 'utf8'));
check('reference: data reaches the frozen date', B.KOLD[B.KOLD.length - 1].date === ASOF);
for (const [k, r] of [['A', refA], ['K', refK]]) {
    check(`reference ${k}: entries`, r.n === FROZEN[k].n, `${r.n} vs ${FROZEN[k].n}`);
    check(`reference ${k}: worked`, r.worked === FROZEN[k].worked, `${r.worked} vs ${FROZEN[k].worked}`);
    check(`reference ${k}: any-day worked %`, Math.abs(r.any.workedPct - FROZEN[k].anyPct) < 0.6, r.any.workedPct.toFixed(2));
}

// ── Part 2: the site's engine ───────────────────────────────────────────────────────────────
if (!fs.existsSync('docs/js/cycle-engine.js')) {
    console.log('BUILD PENDING: docs/js/cycle-engine.js not present; engine checks skipped.');
} else {
    globalThis.CONFIG = ctx.__C; globalThis.VolumeStudies = VS;
    const CE = require('../docs/js/cycle-engine.js'); globalThis.CycleEngine = CE;
    const AE = require('../docs/js/alert-engine.js');
    const same = (a, b) => a.n === b.n && a.worked === b.worked && Math.abs(a.run - b.run) < 0.5 && Math.abs(a.heat - b.heat) < 0.5 && Math.abs(a.nearLowPct - b.nearLowPct) < 0.5;
    check('CycleEngine.record matches the reference (A)', same(CE.record(wA.c, wA.m), refA));
    check('CycleEngine.record matches the reference (K)', same(CE.record(wK.c, wK.m), refK));
    const cut = rows => rows.filter(r => r.date <= ASOF);
    const cvol = cut(AE.parseCvolCsv(fs.readFileSync('docs/data/cvol/ngvl_cvol_history.csv', 'utf8')));
    const fl = AE.flowMap(JSON.parse(fs.readFileSync('docs/data/flows/BOIL_flows.json', 'utf8')));
    const model = AE.compute(B.BOIL, B.KOLD, cvol, fl, B.HNU, B.HND);
    const by = Object.fromEntries(model.setups.map(s => [s.key, s]));
    for (const [key, ref, mask, dates, tier] of [['SHORT_ACCUMULATION', refA, wA.m, wA.dates, 'STRONG'], ['SHORT_LEG_REVERSAL', refK, wK.m, wK.dates, 'MODERATE']]) {
        const s = by[key]; check(`${key}: setup exists`, !!s); if (!s) continue;
        const live = new Map(model.frame.dates.map((d, i) => [d, !!s.mask[i]])); let diff = 0;
        dates.forEach((d, i) => { if (i >= 60 && live.has(d) && live.get(d) !== !!mask[i]) diff++; });
        check(`${key}: trigger days equal the reference`, diff === 0, diff + ' sessions differ');
        check(`${key}: cycle record equals the reference`, s.cycle && s.cycle.us && s.cycle.us.n === ref.n && s.cycle.us.worked === ref.worked, s.cycle ? JSON.stringify(s.cycle.us) : 'no cycle field');
        check(`${key}: Toronto record present`, !!(s.cycle && s.cycle.ca && s.cycle.ca.n > 0));
        check(`${key}: tier ${tier}`, s.tier === tier, String(s.tier));
    }
    for (const s of model.setups) check(`${s.key}: has a cycle record`, !!(s.cycle && s.cycle.us && typeof s.cycle.us.n === 'number'));
    check('CLOSE_EXHAUSTION: tier MODERATE', by.CLOSE_EXHAUSTION && by.CLOSE_EXHAUSTION.tier === 'MODERATE');
    const grid = AE._statGrid(by.SHORT_ACCUMULATION || model.setups[0]);
    for (const lab of ['WORKED', 'ANY DAY', 'TYPICAL RUN', 'TYPICAL HEAT', 'TURNS CAUGHT', 'TORONTO']) check(`card shows ${lab}`, grid.includes(lab));
    // Wording: user-facing text only (comment lines are skipped).
    const text = f => fs.readFileSync(f, 'utf8').split('\n').filter(l => !/^\s*(\/\/|\*|\/\*)/.test(l)).join('\n');
    const BANNED = {
        'docs/index.html': ['P-VALUE', 'p-value', 'TESTED', 'NO EDGE', 'did not change the odds'],
        'docs/js/alert-engine.js': ['P-VALUE', 'p-value', 'SMALL SAMPLE', 'ANY-DAY RATE', 'binomial', 'base rate', 'significan'],
        'docs/js/volume-studies.js': ['TESTED', 'NO EDGE', 'indicator_evidence'],
        'docs/js/signals.js': ['Spearman', 'base rate'],
        'docs/cvol.html': ['BACKTEST', 'base rate', 'significan', 'hit rate'],
        'docs/js/cvol-ui.js': ['NO EDGE', 'MARGINAL', 'p-value', 'ANY-DAY', 'Backtest', 'base rate', 'significan', 'binomial', 'hit rate', 'HIT RATE', 'sample size'],
        'docs/js/cvol.js': ['NO EDGE', 'Backtest', 'base rate', 'hit rate'],
    };
    for (const [f, words] of Object.entries(BANNED)) { const t = text(f), hit = words.filter(w => t.includes(w)); check(`wording: ${f}`, hit.length === 0, hit.join(', ')); }
    const REQUIRED = {
        'docs/js/alert-engine.js': ['AT 63-SESSION LOW', 'CAUTION: QUIET MARKET', 'CAUTION: OPTIONS UPSIDE STRESS', 'LONG-SIDE DIP BUYING', 'PUT-SKEW EXTREME', 'EXIT WATCH', 'PLAN', 'FEW TRADES'],
        'docs/js/volume-studies.js': ['63-SESSION POSITION', 'WASHED OUT', 'STRETCHED'],
        'docs/trough-peak.html': ['CURRENT LEG'],
        'docs/cvol.html': ['HISTORY AND METHODS'],
    };
    for (const [f, words] of Object.entries(REQUIRED)) { const src = fs.readFileSync(f, 'utf8'), miss = words.filter(w => !src.includes(w)); check(`present: ${f}`, miss.length === 0, miss.join(', ')); }
    check('removed: indicator_evidence.json', !fs.existsSync('docs/data/indicator_evidence.json'));
}
console.log(failed ? `FAILED: ${failed} check(s)` : 'PASS cycle acceptance');
process.exit(failed ? 1 : 0);
